import numpy as np

def row_with_max_sum(matrix):
    sums = np.sum(matrix, axis=1)
    return np.argmax(sums)

mat = np.array([[1, 2, 3], [4, 5, 6], [0, 1, 0]])
print(row_with_max_sum(mat)) # Output: 1

import numpy as np

def col_min_indices(arr):
    return np.argmin(arr, axis=0)

print(col_min_indices(np.array([[5, 2], [1, 8]]))) # Output: [1, 0]

